package com.example.workout.workout.mapper;
import com.example.workout.workout.entity.*; import com.example.workout.workout.model.*; import java.util.*;
public final class WorkoutEntityMapper { private WorkoutEntityMapper(){throw new UnsupportedOperationException("This class should never be instantiated");}
 public static WorkoutEntity toEntity(Workout model){ if(model==null)return null; WorkoutEntity e=WorkoutEntity.builder().withId(model.getId()).withWorkoutDate(model.getWorkoutDate()).withName(model.getName()).withWorkoutType(model.getWorkoutType()).withDescription(model.getDescription()).withNotes(model.getNotes()).withDistanceMeters(model.getDistanceMeters()).withDurationSeconds(model.getDurationSeconds()).withMovingTimeSeconds(model.getMovingTimeSeconds()).withAveragePaceSecondsPerKm(model.getAveragePaceSecondsPerKm()).withBestPaceSecondsPerKm(model.getBestPaceSecondsPerKm()).withAverageHeartRate(model.getAverageHeartRate()).withMaxHeartRate(model.getMaxHeartRate()).withAverageCadence(model.getAverageCadence()).withMaxCadence(model.getMaxCadence()).withAveragePowerWatts(model.getAveragePowerWatts()).withMaxPowerWatts(model.getMaxPowerWatts()).withElevationGainMeters(model.getElevationGainMeters()).withElevationLossMeters(model.getElevationLossMeters()).withMinimumElevationMeters(model.getMinimumElevationMeters()).withMaximumElevationMeters(model.getMaximumElevationMeters()).withCalories(model.getCalories()).withAverageStrideLengthMeters(model.getAverageStrideLengthMeters()).withVerticalOscillationCm(model.getVerticalOscillationCm()).withGroundContactTimeMs(model.getGroundContactTimeMs()).withPerceivedEffort(model.getPerceivedEffort()).withFeeling(model.getFeeling()).withCompleted(model.getCompleted()).withTemperatureCelsius(model.getTemperatureCelsius()).withHumidityPercent(model.getHumidityPercent()).withWindSpeedKph(model.getWindSpeedKph()).withWeather(model.getWeather()).withLocation(model.getLocation()).withRouteName(model.getRouteName()).withSource(model.getSource()).withExternalActivityId(model.getExternalActivityId()).withShoeId(model.getShoeId()).withCreatedAt(model.getCreatedAt()).withUpdatedAt(model.getUpdatedAt()).build(); replaceChildren(e,model); return e; }
 public static Workout toModel(WorkoutEntity e){ if(e==null)return null; Workout m=Workout.builder().withId(e.getId()).withWorkoutDate(e.getWorkoutDate()).withName(e.getName()).withWorkoutType(e.getWorkoutType()).withDescription(e.getDescription()).withNotes(e.getNotes()).withDistanceMeters(e.getDistanceMeters()).withDurationSeconds(e.getDurationSeconds()).withMovingTimeSeconds(e.getMovingTimeSeconds()).withAveragePaceSecondsPerKm(e.getAveragePaceSecondsPerKm()).withBestPaceSecondsPerKm(e.getBestPaceSecondsPerKm()).withAverageHeartRate(e.getAverageHeartRate()).withMaxHeartRate(e.getMaxHeartRate()).withAverageCadence(e.getAverageCadence()).withMaxCadence(e.getMaxCadence()).withAveragePowerWatts(e.getAveragePowerWatts()).withMaxPowerWatts(e.getMaxPowerWatts()).withElevationGainMeters(e.getElevationGainMeters()).withElevationLossMeters(e.getElevationLossMeters()).withMinimumElevationMeters(e.getMinimumElevationMeters()).withMaximumElevationMeters(e.getMaximumElevationMeters()).withCalories(e.getCalories()).withAverageStrideLengthMeters(e.getAverageStrideLengthMeters()).withVerticalOscillationCm(e.getVerticalOscillationCm()).withGroundContactTimeMs(e.getGroundContactTimeMs()).withPerceivedEffort(e.getPerceivedEffort()).withFeeling(e.getFeeling()).withCompleted(e.getCompleted()).withTemperatureCelsius(e.getTemperatureCelsius()).withHumidityPercent(e.getHumidityPercent()).withWindSpeedKph(e.getWindSpeedKph()).withWeather(e.getWeather()).withLocation(e.getLocation()).withRouteName(e.getRouteName()).withSource(e.getSource()).withExternalActivityId(e.getExternalActivityId()).withShoeId(e.getShoeId()).withCreatedAt(e.getCreatedAt()).withUpdatedAt(e.getUpdatedAt()).build(); e.getSegments().forEach(x->m.getSegments().add(WorkoutSegment.builder().withId(x.getId()).withPosition(x.getPosition()).withSegmentType(x.getSegmentType()).withName(x.getName()).withRepetitions(x.getRepetitions()).withDistanceMeters(x.getDistanceMeters()).withDurationSeconds(x.getDurationSeconds()).withTargetPaceSecondsPerKm(x.getTargetPaceSecondsPerKm()).withActualPaceSecondsPerKm(x.getActualPaceSecondsPerKm()).withRestDistanceMeters(x.getRestDistanceMeters()).withRestDurationSeconds(x.getRestDurationSeconds()).withAverageHeartRate(x.getAverageHeartRate()).withMaxHeartRate(x.getMaxHeartRate()).withAverageCadence(x.getAverageCadence()).withAveragePowerWatts(x.getAveragePowerWatts()).withElevationGainMeters(x.getElevationGainMeters()).withDescription(x.getDescription()).build())); e.getLaps().forEach(x->m.getLaps().add(WorkoutLap.builder().withId(x.getId()).withPosition(x.getPosition()).withDistanceMeters(x.getDistanceMeters()).withDurationSeconds(x.getDurationSeconds()).withPaceSecondsPerKm(x.getPaceSecondsPerKm()).withAverageHeartRate(x.getAverageHeartRate()).withMaxHeartRate(x.getMaxHeartRate()).withAverageCadence(x.getAverageCadence()).withAveragePowerWatts(x.getAveragePowerWatts()).withElevationGainMeters(x.getElevationGainMeters()).withElevationLossMeters(x.getElevationLossMeters()).build())); e.getTrackPoints().forEach(x->m.getTrackPoints().add(WorkoutTrackPoint.builder().withId(x.getId()).withPosition(x.getPosition()).withRecordedAt(x.getRecordedAt()).withLatitude(x.getLatitude()).withLongitude(x.getLongitude()).withElevationMeters(x.getElevationMeters()).withHeartRate(x.getHeartRate()).withCadence(x.getCadence()).withPowerWatts(x.getPowerWatts()).build())); return m; }
 public static void replaceChildren(WorkoutEntity e, Workout m){ e.getSegments().clear(); for(WorkoutSegment x:m.getSegments()){ e.getSegments().add(WorkoutSegmentEntity.builder().withWorkout(e).withPosition(x.getPosition()).withSegmentType(x.getSegmentType()).withName(x.getName()).withRepetitions(x.getRepetitions()).withDistanceMeters(x.getDistanceMeters()).withDurationSeconds(x.getDurationSeconds()).withTargetPaceSecondsPerKm(x.getTargetPaceSecondsPerKm()).withActualPaceSecondsPerKm(x.getActualPaceSecondsPerKm()).withRestDistanceMeters(x.getRestDistanceMeters()).withRestDurationSeconds(x.getRestDurationSeconds()).withAverageHeartRate(x.getAverageHeartRate()).withMaxHeartRate(x.getMaxHeartRate()).withAverageCadence(x.getAverageCadence()).withAveragePowerWatts(x.getAveragePowerWatts()).withElevationGainMeters(x.getElevationGainMeters()).withDescription(x.getDescription()).build()); } e.getLaps().clear(); for(WorkoutLap x:m.getLaps()){e.getLaps().add(WorkoutLapEntity.builder().withWorkout(e).withPosition(x.getPosition()).withDistanceMeters(x.getDistanceMeters()).withDurationSeconds(x.getDurationSeconds()).withPaceSecondsPerKm(x.getPaceSecondsPerKm()).withAverageHeartRate(x.getAverageHeartRate()).withMaxHeartRate(x.getMaxHeartRate()).withAverageCadence(x.getAverageCadence()).withAveragePowerWatts(x.getAveragePowerWatts()).withElevationGainMeters(x.getElevationGainMeters()).withElevationLossMeters(x.getElevationLossMeters()).build());} e.getTrackPoints().clear(); for(WorkoutTrackPoint x:m.getTrackPoints()){e.getTrackPoints().add(WorkoutTrackPointEntity.builder().withWorkout(e).withPosition(x.getPosition()).withRecordedAt(x.getRecordedAt()).withLatitude(x.getLatitude()).withLongitude(x.getLongitude()).withElevationMeters(x.getElevationMeters()).withHeartRate(x.getHeartRate()).withCadence(x.getCadence()).withPowerWatts(x.getPowerWatts()).build());} }
}
